mapper.select:
SELECT COUNT(*)
  FROM biz02_person
 WHERE biz02_promo_id = #{promoId}
   AND biz02_emp_id   = #{empId}

SELECT COUNT(*)
  FROM biz01_promo
 WHERE biz01_promo_id   = #{promoId}
   AND biz01_company_id = #{companyId}

mapper.delete:
DELETE FROM biz02_person
 WHERE biz02_person_id = #{personId}
   AND biz02_promo_id IN (SELECT biz01_promo_id FROM biz01_promo WHERE biz01_company_id = #{companyId})

mapper.select:
