  FROM biz04_provide_setup
 WHERE biz04_company_id         = #{companyId}
   AND biz04_provide_content_cd = #{provideContentCode}

mapper.update:
UPDATE biz02_person
   SET biz02_target_company_nm = #{targetCompanyName}
     , biz02_target_emp_nm     = #{targetEmpName}
 WHERE biz02_promo_id = #{promoId}
